package com.coffeeshop.service;import com.coffeeshop.model.NotificationModels;import com.coffeeshop.repository.NotificationRepository;import java.util.*;public final class NotificationService{private final NotificationRepository repository;public NotificationService(NotificationRepository r){repository=Objects.requireNonNull(r);}public List<NotificationModels.Notification>notifications(long user,Boolean read){if(user<=0)throw new IllegalArgumentException("An authenticated user is required.");return repository.find(user,read);}public void markRead(NotificationModels.Notification n,long user){Objects.requireNonNull(n);if(n.read())return;if(user<=0)throw new IllegalArgumentException("An authenticated user is required.");repository.markRead(n.id(),user,n.version());}public int generateLowStock(boolean authorized){if(!authorized)throw new SecurityException("Manager or administrator access is required.");return repository.generateLowStockAlerts();}}
